const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{engine}=require('../pace_v0672.cjs');
const hash=x=>crypto.createHash('sha256').update(x).digest('hex'),source='github-release/index.html',bytes=fs.readFileSync(source),prior=fs.readFileSync('github-release/docs/data/counter-cost-0.6.122.json');
assert.equal(hash(bytes),'af1a22ed4e0ed1bdaa7cafccc8fa6d4ab871c6c2f9c72daf933f1aff62f256a4');assert.equal(hash(prior),'fd8160ee6da0866c14ce55ebc4312ef4fc7828abc87a382051108b29de388513');
const {E}=engine(source),offsets=[[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]];
const distances=Array.from({length:90},(_,start)=>{
  const row=Array(90).fill(Infinity),queue=[start];row[start]=0;
  for(let i=0;i<queue.length;i++)for(const [dx,dy]of offsets){const x=queue[i]%9+dx,y=Math.floor(queue[i]/9)+dy,k=y*9+x;if(x>=0&&x<9&&y>=0&&y<10&&!Number.isFinite(row[k])){row[k]=row[queue[i]]+1;queue.push(k);}}
  assert.equal(queue.length,90);return row;
});
let checkedPairs=0;
for(let start=0;start<90;start++){
  const oracle=Array(90).fill(Infinity),queue=[start];oracle[start]=0;
  for(let i=0;i<queue.length;i++){
    const p=E.piece('horse','red','horse',queue[i]%9,Math.floor(queue[i]/9));
    for(const m of E.moves({pieces:[p]},p)){const k=m.y*9+m.x;if(!Number.isFinite(oracle[k])){oracle[k]=oracle[queue[i]]+1;queue.push(k);}}
  }
  assert.deepEqual(distances[start],oracle);
  for(let target=0;target<90;target++){assert.equal(distances[start][target],distances[target][start]);checkedPairs++;}
}
const games=JSON.parse(prior).reports.flatMap(r=>r.runs).filter(r=>r.input.models.red==='baseline'&&r.input.models.black==='baseline');
const report={sourceSHA256:hash(bytes),priorSHA256:hash(prior),checkedPairs,staticDistanceMax:Math.max(...distances.flat()),scope:'36份旧原版记录；马的无阻挡最短走法距离，仅诊断，不改正式评分',runs:[]};
for(const [index,game]of games.entries()){
  let s;const moves=[],samples=[];
  const metric=(p,pieces)=>{const targets=pieces.filter(q=>q.side!==p.side);return {manhattan:Math.min(...targets.map(q=>Math.abs(p.x-q.x)+Math.abs(p.y-q.y))),horseSteps:Math.min(...targets.map(q=>distances[p.y*9+p.x][q.y*9+q.x]))};};
  for(const [commandIndex,[op,...args]]of game.commands.entries()){
    if(op==='create'){s=E.create(...args);continue;}
    if(s.phase==='board'&&s.quiet>=20){
      const horses=s.pieces.filter(p=>p.side===s.turn&&p.kind==='horse');
      if([20,40,60,79].includes(s.quiet)&&horses.length)samples.push({ply:s.ply+1,commandIndex,quiet:s.quiet,horses:horses.map(p=>({id:p.id,from:[p.x,p.y],...metric(p,s.pieces)}))});
      const p=op==='move'?E.get(s,args[0]):null;
      if(p?.kind==='horse'&&!E.at(s,args[1],args[2])){
        const before=metric(p,s.pieces),after=metric({...p,x:args[1],y:args[2]},s.pieces);
        moves.push({ply:s.ply+1,commandIndex,quiet:s.quiet,id:p.id,from:[p.x,p.y],to:[args[1],args[2]],before,after,closerManhattanFartherHorse:after.manhattan<before.manhattan&&after.horseSteps>before.horseSteps,fartherManhattanCloserHorse:after.manhattan>before.manhattan&&after.horseSteps<before.horseSteps});
      }
    }
    E[op](s,...args);
  }
  assert.equal(hash(JSON.stringify(s)),game.terminalSHA256);report.runs.push({index,input:game.input,plies:s.ply,moves,samples});
}
const fresh=report.runs.filter(r=>r.input.group!=='known'),moves=fresh.flatMap(r=>r.moves);
report.summary={newRootGames:fresh.length,oldControls:report.runs.length-fresh.length,lateHorseMoves:moves.length,closerManhattanFartherHorse:moves.filter(r=>r.closerManhattanFartherHorse).length,fartherManhattanCloserHorse:moves.filter(r=>r.fartherManhattanCloserHorse).length,boundarySamplesWithHorse:fresh.reduce((n,r)=>n+r.samples.length,0)};
assert.equal(hash(fs.readFileSync(source)),report.sourceSHA256);fs.writeFileSync(__dirname+'/audit.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({...report,runs:undefined}));
console.log(JSON.stringify(fresh.flatMap(r=>r.moves.filter(m=>m.closerManhattanFartherHorse).map(m=>({index:r.index,input:r.input,...m}))).slice(0,5),null,2));

